import React, { useState } from 'react';
import './Calendrier.css';
import AjouterTrajet from './AjouterTrajet';

const Calendrier = () => {
  const [activeTab, setActiveTab] = useState("Semaine");
  const [showModal, setShowModal] = useState(false);

  // Onglets simplifiés
  const tabs = ["Aujourd'hui", "Personne", "Semaine"];

  return (
    <div className="page-content full-width">
      {/* Header */}
      <div className="calendrier-header">
        {/* Tabs */}
        <div className="tabs-container">
          {tabs.map(tab => (
            <button
              key={tab}
              className={`tab-button ${activeTab === tab ? 'active' : ''}`}
              onClick={() => setActiveTab(tab)}
            >
              {tab}
            </button>
          ))}
        </div>

        {/* Bouton Ajouter un trajet */}
        <div className="add-trajet-container">
          <button 
            className="add-trajet-btn"
            onClick={() => setShowModal(true)}
          >
            <span>+</span> Ajouter un trajet
          </button>
        </div>
      </div>

      {/* Grille du calendrier (reste inchangé) */}
      <div className="calendrier-grid">
        {/* ... ton code pour la grille du calendrier ... */}
      </div>

      {/* Modale Ajouter Trajet */}
      <AjouterTrajet 
        isOpen={showModal}
        onClose={() => setShowModal(false)}
        onSave={(data) => {
          console.log("Trajet enregistré", data);
          setShowModal(false);
        }}
      />
    </div>
  );
};

export default Calendrier;
